// Command specgen converts the Swagger 2.0 document generated by swag
// (docs/swagger.json) into an OpenAPI 3 document (docs/openapi.yaml). The
// OpenAPI 3 document is embedded in the binary and served to Scalar.
//
// Run it after every `swag init` invocation:
//
//	swag init -g main.go -d ./cmd/api,./internal -o docs
//	go run ./cmd/specgen
package main

import (
	"encoding/json"
	"fmt"
	"os"

	"github.com/getkin/kin-openapi/openapi2"
	"github.com/getkin/kin-openapi/openapi2conv"
	"github.com/getkin/kin-openapi/openapi3"
	"gopkg.in/yaml.v3"
)

const (
	source = "docs/swagger.json"
	target = "docs/openapi.yaml"
)

func main() {
	if err := run(); err != nil {
		fmt.Fprintf(os.Stderr, "specgen: %v\n", err)
		os.Exit(1)
	}
}

func run() error {
	data, err := os.ReadFile(source)
	if err != nil {
		return fmt.Errorf("read %s: %w", source, err)
	}

	var doc2 openapi2.T
	if err := json.Unmarshal(data, &doc2); err != nil {
		return fmt.Errorf("parse %s: %w", source, err)
	}

	doc3, err := openapi2conv.ToV3(&doc2)
	if err != nil {
		return fmt.Errorf("convert %s to OpenAPI 3: %w", source, err)
	}

	// The Swagger document only carries the base path, so promote it to the
	// server URL to keep Scalar's "Try it" requests pointed at the right routes.
	if doc2.BasePath != "" {
		doc3.Servers = openapi3.Servers{{URL: doc2.BasePath}}
	}

	// Swagger 2.0 has no bearer scheme, so swag declares BearerAuth as an API
	// key in the Authorization header. Describe it as HTTP bearer auth instead
	// so Scalar renders a proper token input.
	if doc3.Components != nil {
		if bearer := doc3.Components.SecuritySchemes["BearerAuth"]; bearer != nil && bearer.Value != nil {
			bearer.Value.Type = "http"
			bearer.Value.Scheme = "bearer"
			bearer.Value.In = ""
			bearer.Value.Name = ""
		}
	}

	data, err = yaml.Marshal(doc3)
	if err != nil {
		return fmt.Errorf("marshal OpenAPI 3 document: %w", err)
	}

	if err := os.WriteFile(target, data, 0o644); err != nil {
		return fmt.Errorf("write %s: %w", target, err)
	}

	return nil
}
